// Extract component name from topic: jctsh/<type>/<component>/heartbeat
const parts = msg.topic.split('/');
const component = parts.length >= 3 ? parts[2] : 'unknown';

// Component is reporting again -- clear the 35-min silence timer AND any
// active re-alert interval (CARD-0331: without this, a component that
// recovers mid-outage would keep getting "still silent" pushes forever).
const existingTimer = context.get(component + '_timer');
if (existingTimer) clearTimeout(existingTimer);
const existingInterval = context.get(component + '_repeatInterval');
if (existingInterval) clearInterval(existingInterval);
context.set(component + '_repeatInterval', null);
context.set(component + '_downSince', null);

node.warn('Timer set for ' + component + ' — will fire in 35 min');

const timer = setTimeout(function() {
    context.set(component + '_timer', null);
    const downSince = Date.now();
    context.set(component + '_downSince', downSince);
    node.warn('Timer fired for ' + component);
    node.send({ payload: component });

    // CARD-0331: a single alert made a 35-min outage and a multi-hour
    // outage indistinguishable in the alert stream. Re-fire every 2h
    // while still silent, until a heartbeat (above) clears this interval.
    const interval = setInterval(function() {
        const downtimeMinutes = Math.round((Date.now() - downSince) / 60000);
        node.send({ payload: { component: component, downtimeMinutes: downtimeMinutes } });
    }, 2 * 60 * 60 * 1000);
    context.set(component + '_repeatInterval', interval);
}, 35 * 60 * 1000);

context.set(component + '_timer', timer);

// No output on receipt — only fires on timeout
return null;

const isRepeat = typeof msg.payload === 'object' && msg.payload !== null;
const component = isRepeat ? msg.payload.component : msg.payload;
const HA_URL   = 'http://localhost:8123';
const HA_TOKEN = env.get('HA_TOKEN') || flow.get('haToken') || global.get('haToken');

// CARD-0331: format a repeat alert's accumulated downtime as e.g. "2h15m"
// (or "45m" under an hour) -- the initial 35-min alert doesn't need this,
// its own wording already says the duration.
function formatDuration(totalMinutes) {
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return h > 0 ? (h + 'h' + m + 'm') : (m + 'm');
}

const messageText = isRepeat
    ? 'JCTsh alert: ' + component + ' still silent -- down ' + formatDuration(msg.payload.downtimeMinutes)
    : 'JCTsh alert: ' + component + ' has not reported in 35 minutes';
const logText = isRepeat
    ? 'Component ' + component + ' still silent -- down ' + formatDuration(msg.payload.downtimeMinutes)
    : 'Component ' + component + ' silent for 35 minutes';

// Output 1: HA notification request
const haMsg = {
    url: HA_URL + '/api/services/notify/mobile_app_pixel_10_pro_xl',
    method: 'POST',
    headers: {
        'Authorization': 'Bearer ' + HA_TOKEN,
        'Content-Type': 'application/json'
    },
    payload: JSON.stringify({
        message: messageText,
        title: 'JCTsh Watchdog'
    }),
    _component: component
};

// Output 2: watchdog log message (published regardless of HA result)
const logMsg = {
    payload: JSON.stringify({
        component: 'watchdog',
        category: 'Alert',
        message: logText
    })
};

return [haMsg, logMsg];

const component = msg._component || 'unknown';
node.warn('HA notify status: ' + msg.statusCode + ' | payload: ' + JSON.stringify(msg.payload));
if (msg.statusCode !== 200 && msg.statusCode !== 201) {
    node.warn('HA notify error ' + msg.statusCode + ': ' + msg.payload);
    return { payload: JSON.stringify({
        component: 'watchdog',
        category: 'Alert',
        message: 'HA notify error ' + msg.statusCode + ' — alert for ' + component + ' may not have delivered'
    })};
}
return null;

// CARD-0324: remember when each component last reported, for the daily check
// below. Its own function on the same subscription -- fn_timer_manager (the
// alerting path) is deliberately untouched.
const parts = msg.topic.split('/');
const component = parts.length >= 3 ? parts[2] : 'unknown';
const seen = flow.get('lastHeartbeat') || {};
seen[component] = Date.now();
flow.set('lastHeartbeat', seen);
return null;

// CARD-0324: the watchdog used to speak only when something was wrong, so its
// /status row showed its last outage forever, and its silence couldn't be told
// apart from Node-RED itself being down. A normal System line once a day fixes
// both: it replaces the stale alert as the last message, and if it ever stops
// appearing, the watchdog (or Node-RED) is what died.
// Wording is deliberately neither "Heartbeat - " nor "Watchdog: " -- log_server
// treats those as heartbeats and would expect one every ~70 minutes.
const seen = flow.get('lastHeartbeat') || {};
const now = Date.now();
const SILENT_MS = 35 * 60 * 1000;          // same threshold fn_timer_manager alerts on
const FORGET_MS = 7 * 24 * 60 * 60 * 1000; // stop listing a component gone for a week
const reporting = [];
const silent = [];
for (const c of Object.keys(seen)) {
    const age = now - seen[c];
    if (age > FORGET_MS) { delete seen[c]; continue; }
    (age > SILENT_MS ? silent : reporting).push(c);
}
flow.set('lastHeartbeat', seen);
silent.sort();

let text;
if (reporting.length + silent.length === 0) {
    text = 'Daily check: no component heartbeats seen since Node-RED started';
} else {
    text = 'Daily check: ' + reporting.length + ' component' + (reporting.length === 1 ? '' : 's') +
           ' reporting, ' + silent.length + ' silent';
    if (silent.length) text += ' (' + silent.join(', ') + ')';
}
return { payload: JSON.stringify({ component: 'watchdog', category: 'System', message: text }) };
